interface IIndex {
    fun print()
    val index: Int
}

interface IValue {
    fun print()
    val value: Int
}

class IndexData(override val index: Int) : IIndex {
    override fun print() = print(index)
}

class ValueData(override val value: Int) : IValue {
    override fun print() = print(value)
}

fun getDateTime() = "03-05-2021-14:33"

class LogDataCollector(index: IIndex, value: IValue) : IIndex by index, IValue by value {
    override fun print() = print("[${getDateTime()}]: $index, $value")
}


interface Speed {
    fun increaseSpeed()
    fun decreaseSpeed()
}

interface Fuel {
    fun consumeFuel()
    fun addFuel()
}

class SpeedHandler(private val car: Car) : Speed {
    override fun increaseSpeed() {
        car.speed += 10
    }

    override fun decreaseSpeed() {
        if (car.speed - 10 >= 0) {
            car.speed -= 10
        } else {
            car.speed = 0
        }
    }
}

class FuelHandler(private val car: Car) : Fuel {
    override fun consumeFuel() {
        if (car.fuel - 5 >= 0) {
            car.fuel -= 5
        } else {
            car.fuel = 0
        }
    }

    override fun addFuel() {
        if (car.fuel + 10 <= 100) {
            car.fuel += 10
        } else {
            car.fuel = 100
        }
    }
}

class Car(var speed: Int, var fuel: Int) : Speed, Fuel {
    private val speedDelegate = SpeedHandler(this)
    private val fuelDelegate = FuelHandler(this)
    override fun increaseSpeed() = speedDelegate.increaseSpeed()
    override fun decreaseSpeed() = speedDelegate.decreaseSpeed()
    override fun consumeFuel() = fuelDelegate.consumeFuel()
    override fun addFuel() = fuelDelegate.addFuel()
}

fun Int.opp(f: Int.() -> Int): Int = f()  // то же, что this.f() или f(this)

